import React, { useState } from 'react';
import { Stage, Layer, Line, Circle } from 'react-konva';

const CadConfigurator = () => {
  const [operation, setOperation] = useState('extrude');
  const [points, setPoints] = useState([]);
  const [isFinished, setIsFinished] = useState(false);
  const [bodies, setBodies] = useState([]);
  const [sweepMode, setSweepMode] = useState('profile');
  const [axis, setAxis] = useState('Y');
  const [length, setLength] = useState(100);

  const CANVAS_WIDTH = 600;
  const CANVAS_HEIGHT = 400;
  const GRID_SIZE = 20;

  // Snap coordinate to the nearest grid intersection
  const snapToGrid = (val) => Math.round(val / GRID_SIZE) * GRID_SIZE;

  const handleStageClick = (e) => {
    if (isFinished) return;
    const pos = e.target.getStage().getPointerPosition();
    const snappedX = snapToGrid(pos.x);
    const snappedY = snapToGrid(pos.y);
    setPoints([...points, snappedX, snappedY]);
  };

  const handleDoubleClick = () => {
    if (points.length >= 6) setIsFinished(true);
  };

  const clear = () => {
    setPoints([]);
    setIsFinished(false);
  };

  const saveBody = () => {
    const vertices = [];
    for (let i = 0; i < points.length; i += 2) {
      vertices.push([points[i], points[i + 1]]);
    }
    setBodies([...bodies, { type: sweepMode, vertices, is_closed: isFinished }]);
    clear();
  };

  const generatePayload = () => {
    const vertices = [];
    for (let i = 0; i < points.length; i += 2) {
      vertices.push([points[i], points[i + 1]]);
    }

    let payload = { operation_type: operation };

    if (operation === 'extrude') {
      payload.length = length;
      payload.profile = { vertices, is_closed: isFinished };
    } else if (operation === 'revolve') {
      payload.axis_of_rotation = axis === 'Y' ? [0, 1, 0] : [1, 0, 0];
      payload.degrees = 360;
      payload.profile = { vertices, is_closed: isFinished };
    } else if (operation === 'sweep') {
      payload.cross_section = bodies.find(b => b.type === 'profile') || {};
      payload.sweep_path = bodies.find(b => b.type === 'path') || {};
    } else if (operation === 'union') {
      payload.bodies = bodies.map(b => ({ type: 'extrude', profile: b, length }));
    }

    console.log("Payload:", JSON.stringify(payload, null, 2));
  };

  // Generate background grid lines
  const gridLines = [];
  for (let i = 0; i <= CANVAS_WIDTH / GRID_SIZE; i++) {
    gridLines.push(
      <Line key={`v-${i}`} points={[i * GRID_SIZE, 0, i * GRID_SIZE, CANVAS_HEIGHT]} stroke={i % 5 === 0 ? "#ccc" : "#eee"} strokeWidth={1} />
    );
  }
  for (let j = 0; j <= CANVAS_HEIGHT / GRID_SIZE; j++) {
    gridLines.push(
      <Line key={`h-${j}`} points={[0, j * GRID_SIZE, CANVAS_WIDTH, j * GRID_SIZE]} stroke={j % 5 === 0 ? "#ccc" : "#eee"} strokeWidth={1} />
    );
  }

  return (
    <div className="flex flex-col items-center p-4 font-sans text-sm">
      <div className="flex gap-4 mb-4 items-center">
        <select value={operation} onChange={(e) => { setOperation(e.target.value); setBodies([]); clear(); }} className="border p-1">
          <option value="extrude">Extrude</option>
          <option value="revolve">Revolve</option>
          <option value="sweep">Sweep</option>
          <option value="union">Union</option>
        </select>
        {operation === 'extrude' && <input type="number" value={length} onChange={(e) => setLength(Number(e.target.value))} className="border p-1 w-20" />}
        {operation === 'revolve' && (
          <select value={axis} onChange={(e) => setAxis(e.target.value)} className="border p-1">
            <option value="Y">Y-Axis</option>
            <option value="X">X-Axis</option>
          </select>
        )}
        {operation === 'sweep' && (
          <select value={sweepMode} onChange={(e) => setSweepMode(e.target.value)} className="border p-1">
            <option value="profile">Profile</option>
            <option value="path">Path</option>
          </select>
        )}
        {(operation === 'sweep' || operation === 'union') && <button onClick={saveBody} className="bg-gray-200 px-3 py-1">Save Part</button>}
      </div>

      <div className="border-2 border-gray-400 bg-white cursor-crosshair shadow-sm">
        <Stage width={CANVAS_WIDTH} height={CANVAS_HEIGHT} onClick={handleStageClick} onDblClick={handleDoubleClick}>
          <Layer>
            {/* Background Grid */}
            {gridLines}
          </Layer>
          <Layer>
            {/* User Drawing */}
            <Line points={points} stroke="#2563eb" strokeWidth={3} closed={isFinished} lineJoin="round" />
            {points.map((p, i) => i % 2 === 0 ? <Circle key={i} x={points[i]} y={points[i + 1]} radius={4} fill="#dc2626" /> : null)}
          </Layer>
        </Stage>
      </div>

      <div className="mt-4 flex gap-4">
        <button onClick={clear} className="px-4 py-2 bg-red-500 text-white hover:bg-red-600">Clear</button>
        <button onClick={generatePayload} className="px-4 py-2 bg-blue-600 text-white hover:bg-blue-700">Generate JSON</button>
      </div>
    </div>
  );
};

export default CadConfigurator;
